-- Windows-specific agenda, combining existing orgmode.lua and user_orgmode.lua.
-- The local configuration is generated by windows/install-orgmode.ps1 and NOT committed.
return {
  "nvim-orgmode/orgmode",
  event = "VeryLazy",
  ft = { "org", "orgagenda" },
  config = function()
    local ok, settings = pcall(require, "config.orgmode_windows")
    if not ok or type(settings) ~= "table" or type(settings.root) ~= "string" or settings.root == "" then
      vim.notify("Orgmode Windows: configure your local .org folder first", vim.log.levels.WARN)
      return
    end

    local root = vim.fn.expand(settings.root):gsub("\\", "/"):gsub("/+$", "")
    require("orgmode").setup({
      org_agenda_files = { root .. "/**/*.org", root .. "/*.org" },
      org_default_notes_file = root .. "/Seguimiento_Actividades.org",
      org_todo_keywords = { "TODO(t)", "IN_PROGRESS(i)", "|", "DONE(d)", "CANCELLED(c)" },
      org_todo_keyword_faces = {
        TODO = ":foreground #f7768e :weight bold",
        IN_PROGRESS = ":foreground #e0af68 :weight bold",
        DONE = ":foreground #73daca :weight bold",
        CANCELLED = ":foreground #565f89 :weight bold",
      },
      org_agenda_span = "week",
      org_agenda_start_on_weekday = 1,
      org_indent_mode = "indent",
    })

    local function highlights()
      local function set(group, opts)
        vim.api.nvim_set_hl(0, group, vim.tbl_extend("force", opts, { force = true }))
      end
      set("OrgAgendaScheduled", { fg = "#e2e8f0" })
      set("@org.agenda.scheduled", { fg = "#e2e8f0" })
      set("OrgAgendaScheduledPast", { fg = "#e0af68" })
      set("@org.agenda.scheduled_past", { fg = "#e0af68" })
      set("OrgPriorityA", { fg = "#f7768e", bold = true })
      set("@org.priority.highest", { fg = "#f7768e", bold = true })
      set("OrgPriorityB", { fg = "#9ece6a", bold = true })
      set("@org.priority.default", { fg = "#9ece6a", bold = true })
      set("OrgPriorityC", { fg = "#565f89", bold = false })
      set("@org.priority.lowest", { fg = "#565f89", bold = false })
    end
    highlights()
    vim.api.nvim_create_autocmd("ColorScheme", { callback = highlights })
  end,
}
